///- --test
///> zig

inl ~e = "no"
Error e |> then_ok (fun (x : i32) => Ok (x + 1)) |> _assert_eq (Error "no")

///- --test
///> zig

inl ~n = 2i32
inl l = [1i32; 2; 3; 4]
keep (fun x => x > n) l |> listm.length |> _assert_eq 2i32
first_where (fun x => x > n) l |> _assert_eq (Some 3i32)
